const CLOUD_URL='https://dojpymvpdmuxbcxllwne.supabase.co';
const CLOUD_KEY='sb_publishable_Nvk61pQDRiq3bira6esxxQ_Y9YTWTY3';
let cloudSession=null,cloudVersion=0,cloudReady=false,cloudSaving=false,cloudPending=null,cloudBlocked=false,cloudStatus='Conectado',cloudWaiters=[];
try{cloudSession=JSON.parse(localStorage.getItem('comissions-auth-session'));}catch{}
async function authRequest(path,body){const response=await fetch(CLOUD_URL+'/auth/v1/'+path,{method:'POST',headers:{apikey:CLOUD_KEY,'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw Error(result.msg||result.error_description||result.message||'Não foi possível entrar.');return result;}
async function api(action,extra={},anonymous=false){if(!anonymous&&cloudSession&&cloudSession.expires_at<Date.now()/1000+60){cloudSession=await authRequest('token?grant_type=refresh_token',{refresh_token:cloudSession.refresh_token});localStorage.setItem('comissions-auth-session',JSON.stringify(cloudSession));}const response=await fetch(CLOUD_URL+'/functions/v1/comissions-api',{method:'POST',headers:{apikey:CLOUD_KEY,'Content-Type':'application/json',...(!anonymous&&cloudSession?{Authorization:'Bearer '+cloudSession.access_token}:{})},body:JSON.stringify({action,...extra})});const result=await response.json();if(!response.ok)throw Error(result.error||'Falha na conexão.');return result;}
function authScreen(invite=false){cloudReady=false;document.body.classList.remove('auth-pending');document.querySelector('aside').hidden=true;document.querySelector('main').hidden=true;let el=document.getElementById('authScreen');if(!el){el=document.createElement('section');el.id='authScreen';document.body.appendChild(el);}el.hidden=false;el.innerHTML=`<div class="auth-box"><div class="brand">Comissions ↗</div><h1>${invite?'Ativar meu acesso':'Entrar'}</h1><p>${invite?'Defina sua senha para aceitar o convite. O link é válido por 24 horas e só pode ser usado uma vez.':'Acesse os dados das suas empresas com seu e-mail e senha.'}</p><form id="authForm">${invite?'':field('loginEmail','E-mail','','email','required autocomplete="username"')}${field('loginPassword',invite?'Crie uma senha (mínimo 12 caracteres)':'Senha','','password',`required minlength="${invite?12:1}" autocomplete="${invite?'new-password':'current-password'}"`)}${invite?field('confirmPassword','Confirme a senha','','password','required minlength="12" autocomplete="new-password"'):''}<p id="authError" role="alert"></p><button class="btn" id="authSubmit">${invite?'Ativar acesso':'Entrar'}</button></form><p class="small">${invite?'A senha é criada diretamente no Supabase.':'Acesso somente por convite. Se precisar redefinir a senha, fale com o administrador.'}</p></div>`;document.getElementById('authForm').onsubmit=async e=>{e.preventDefault();const submit=document.getElementById('authSubmit'),error=document.getElementById('authError');submit.disabled=true;error.textContent='';try{const f=new FormData(e.target),password=f.get('loginPassword');let email=f.get('loginEmail');if(invite){if(password!==f.get('confirmPassword'))throw Error('As senhas não coincidem.');const token=new URLSearchParams(location.hash.slice(1)).get('invite');const accepted=await api('accept',{token,password},true);email=accepted.email;history.replaceState(null,'',location.pathname);}cloudSession=await authRequest('token?grant_type=password',{email,password});localStorage.setItem('comissions-auth-session',JSON.stringify(cloudSession));await loadCloud();}catch(e){error.textContent=e.message;}finally{submit.disabled=false;}};}
async function loadCloud(){const result=await api('load');assertSafeState(result.state);state=result.state;state.commissionEdits??={};state.commissionPaymentDetails??={};state.commissionHistory??=[];state.commissionPayments??={};state.extraCommissions??=[];state.goals??=[];cloudVersion=result.version;currentUser=result.profile.id;company=['Vendedor','Colaborador','Desenvolvedor'].includes(result.profile.role)&&result.profile.companies.length===1?result.profile.companies[0]:'all';cloudReady=true;cloudBlocked=false;cloudStatus='Sincronizado';page='Visão geral';document.querySelector('aside').hidden=false;document.querySelector('main').hidden=false;document.getElementById('authScreen')?.remove();document.body.classList.remove('auth-pending');render();}
const localRender=render;
render=function(){if(!cloudReady)return;localRender();if(!accessibleModules().length)document.getElementById('app').innerHTML='<section class="panel"><h1>Acesso configurado</h1><p>Nenhum módulo liberado. Solicite ao administrador a liberação dos módulos necessários.</p></section><p></p>';if(!canManage())renderPersonalPortal();document.getElementById('header').innerHTML=`<div><strong>${company==='all'?'Grupo · empresas autorizadas':esc(companyName(company))}</strong><div class="small">${esc(user().name)} · ${esc(user().role)}</div></div><div class="cloud-header"><span class="badge" id="cloudStatus">${esc(cloudStatus)}</span>${btn('Atualizar','refreshCloud()',true)}${btn('Sair','logoutCloud()',true)}</div>`;document.querySelector('aside footer').innerHTML=`${btn('⚙ Minhas configurações','openMySettings()',true)}`;document.querySelector('#app>p:last-child').textContent='Comissions · Dados armazenados no Supabase · Acesso protegido';if(cloudBlocked)document.getElementById('app').insertAdjacentHTML('afterbegin','<div class="notice" role="alert">Sincronização interrompida. Recarregue os dados antes de continuar. Não há alterações locais pendentes salvas no servidor.</div>');if(isAdmin()&&page==='Usuários e acessos')document.getElementById('app').insertAdjacentHTML('afterbegin','<div class="notice">Cadastre a pessoa para gerar um link de convite. Copie e envie manualmente. Links expiram em 24 horas; gerar outro invalida o anterior.</div>');};
save=function(){if(!cloudReady)return;if(cloudBlocked){toast('Atualize os dados antes de continuar.');return;}const copy=structuredClone(state);copy.extraCommissions=(copy.extraCommissions||[]).map(e=>({...e,company:copy.contracts.find(c=>c.id===e.contractId)?.company}));cloudPending=copy;cloudStatus='Salvando…';document.getElementById('cloudStatus')?.replaceChildren(document.createTextNode(cloudStatus));const confirmation=new Promise((resolve,reject)=>cloudWaiters.push({resolve,reject}));confirmation.catch(()=>{});flushCloud();return confirmation;};
async function flushCloud(){if(cloudSaving||!cloudPending||cloudBlocked)return;cloudSaving=true;const snapshot=cloudPending;cloudPending=null;try{const result=await api('save',{state:snapshot,version:cloudVersion});cloudVersion=result.version;for(const c of state.contracts)if(result.codes?.[c.id])c.code=result.codes[c.id];if(cloudPending)for(const c of cloudPending.contracts)if(result.codes?.[c.id])c.code=result.codes[c.id];if(!cloudPending&&result.paymentDetails)state.commissionPaymentDetails=result.paymentDetails;cloudStatus=cloudPending?'Salvando…':'Sincronizado';}catch(e){cloudBlocked=true;cloudPending=null;cloudStatus='Falha ao salvar';toast(e.message+' Atualize os dados antes de continuar.');document.getElementById('modal')?.close();for(const waiter of cloudWaiters.splice(0))waiter.reject(e);document.querySelector('main').inert=true;let blocker=document.createElement('div');blocker.className='cloud-conflict';blocker.innerHTML='<div class="auth-box"><h2>Não foi possível confirmar o salvamento</h2><p id="cloudFailure"></p><button class="btn" onclick="location.reload()">Recarregar dados do servidor</button></div>';document.body.appendChild(blocker);document.getElementById('cloudFailure').textContent=e.message;}finally{cloudSaving=false;document.getElementById('cloudStatus')?.replaceChildren(document.createTextNode(cloudStatus));if(cloudPending&&!cloudBlocked)flushCloud();else if(!cloudBlocked)for(const waiter of cloudWaiters.splice(0))waiter.resolve();}}
async function refreshCloud(){if(cloudSaving||cloudPending)return toast('Aguarde o salvamento.');try{await loadCloud()}catch(e){toast(e.message)}}
async function logoutCloud(){if(cloudSaving||cloudPending)return toast('Aguarde o salvamento.');try{await fetch(CLOUD_URL+'/auth/v1/logout',{method:'POST',headers:{apikey:CLOUD_KEY,Authorization:'Bearer '+cloudSession.access_token}})}catch{}cloudSession=null;state=structuredClone(initial);localStorage.removeItem('comissions-auth-session');authScreen();}
function showInviteLink(result){const m=document.getElementById('modal');if(m.open)m.close();m.innerHTML=`<h2>Convite gerado</h2><p>Envie este link diretamente à pessoa. Ele vale por 24 horas e pode ser usado apenas uma vez.</p><input id="inviteLink" readonly aria-label="Link de convite" value="${esc(result.url)}" style="width:100%"><div class="actions">${btn('Copiar link','copyInviteLink()')}${btn('Fechar',"document.getElementById('modal').close()",true)}</div>`;m.showModal();}
async function copyInviteLink(){const el=document.getElementById('inviteLink');el.select();try{await navigator.clipboard.writeText(el.value);toast('Link copiado.')}catch{document.execCommand('copy');toast('Link selecionado para copiar.')}}
editUser=function(id,seed){if(!isAdmin())return;const u=state.users.find(u=>u.id===id)||seed||{name:'',email:'',role:'Colaborador',all:false,companies:[],active:true};show(`<h2>${id?'Editar acesso':'Convidar usuário'}</h2><form><div class="formgrid">${field('name','Nome',u.name,'text','required')}${field('email','E-mail',u.email,'email',`required ${id?'readonly':''}`)}${select('role','Perfil',['Administrador','Gestor','Vendedor','Desenvolvedor','Colaborador'].map(v=>[v,v]),u.role)}${select('active','Status',[['yes','Ativo'],['no','Inativo']],u.active?'yes':'no')}</div><h3>Empresas autorizadas</h3><p class="small">Selecione pelo menos uma empresa. Vendedores e desenvolvedores precisam de vínculo explícito com a empresa.</p><div class="checks"><label><input name="all" type="checkbox" ${u.all?'checked':''}> Todas as empresas</label>${state.companies.map(c=>`<label><input name="companies" type="checkbox" value="${esc(c.id)}" ${u.companies.includes(c.id)?'checked':''}>${esc(c.name)}</label>`).join('')}</div><h3>Módulos liberados</h3><p class="small">O perfil define as ações. Vendedores, desenvolvedores e colaboradores consultam apenas os próprios registros. Desenvolvedor não lança nem altera vendas. Usuários e acessos é exclusivo do administrador.</p><div class="checks" id="moduleChecks">${moduleNames.map(m=>`<label><input type="checkbox" name="modules" value="${esc(m)}" ${(u.modules||(u.role==='Administrador'?moduleNames:u.role==='Gestor'?moduleNames.slice(0,7):['Vendedor','Colaborador','Desenvolvedor'].includes(u.role)?['Visão geral','Contratos','Comissões']:['Comissões'])).includes(m)?'checked':''}>${esc(m)}</label>`).join('')}</div><p id="userFormError" role="alert" style="color:#b93630" hidden></p>${actions()}</form>`,async f=>{const form=document.getElementById('userFormError').closest('form'),error=document.getElementById('userFormError'),submit=form.querySelector('button[type=submit]');if(submit.disabled)return;error.hidden=true;const profile={id,name:f.get('name'),email:f.get('email'),role:f.get('role'),all:f.has('all'),companies:f.getAll('companies'),modules:f.getAll('modules'),active:f.get('active')==='yes'};try{if(profile.role!=='Administrador'&&(!profile.all||['Vendedor','Desenvolvedor'].includes(profile.role))&&!profile.companies.length)throw Error('Selecione pelo menos uma empresa para este usuário.');submit.disabled=true;submit.textContent='Salvando…';const result=await api(id?'profile':'invite',{profile});await loadCloud();document.getElementById('modal').close();page='Usuários e acessos';render();if(!id)showInviteLink(result);else toast('Acesso atualizado.');}catch(e){error.textContent=e.message||'Não foi possível salvar o usuário.';error.hidden=false;}finally{submit.disabled=false;submit.textContent='Salvar';}});const role=document.getElementById('f_role');role.onchange=()=>configureAccessForm(true);configureAccessForm(false);};
toggleUserActive=async function(id){if(!isAdmin()||id===currentUser)return;const u=state.users.find(u=>u.id===id);try{await api('profile',{profile:{...u,active:!u.active}});await loadCloud();page='Usuários e acessos';render()}catch(e){toast(e.message)}};
copyUserPermissions=function(id){const u=state.users.find(u=>u.id===id);if(u)editUser(undefined,{...u,id:undefined,name:'',email:''});};
function configureAccessForm(reset){const role=document.getElementById('f_role').value,admin=role==='Administrador',seller=['Vendedor','Colaborador','Desenvolvedor'].includes(role);const all=document.querySelector('#modal input[name="all"]');all.disabled=seller||admin;if(seller)all.checked=false;if(admin)all.checked=true;const defaults=admin?moduleNames:role==='Gestor'?moduleNames.slice(0,7):seller?['Visão geral','Contratos','Comissões']:['Comissões'];document.querySelectorAll('#moduleChecks input').forEach(i=>{i.disabled=admin||i.value==='Usuários e acessos';if(reset||admin)i.checked=defaults.includes(i.value);if(!admin&&i.value==='Usuários e acessos')i.checked=false;});}
function renderPersonalPortal(){const root=document.getElementById('app');if(page==='Visão geral'){const list=visible(),t=stats(list),events=accessibleModules().includes('Comissões')?visibleLedger():[],paid=events.filter(x=>x.paidAt).reduce((a,x)=>a+x.amount,0);root.innerHTML=title('Meu painel','Seus contratos e resultados nas empresas autorizadas.',canSell()?btn('+ Nova venda','newSale()'):'')+metric([[moduleLabel('Contratos'),t.n,'Contratos ativos'],['MRR contratado',money(t.m),'Receita dos contratos vinculados'],...(accessibleModules().includes('Comissões')?[['Minhas comissões',money(events.reduce((a,x)=>a+x.amount,0)),'Todos os eventos previstos'],['Comissões pagas',money(paid),'Pagamentos registrados']]:[])])+`<section class="panel"><h2>Contratos recentes</h2>${personalContracts(list.slice(-5))}</section><p>Comissions</p>`;}if(page==='Contratos'){root.innerHTML=title(moduleLabel('Contratos'),canSell()?'Acompanhe seus contratos e lance novas vendas.':'Consulte os contratos em que você participa.',canSell()?btn('+ Nova venda','newSale()'):'')+`<section class="panel"><input aria-label="Buscar minhas vendas" placeholder="Buscar cliente ou contrato…" oninput="query=this.value;document.getElementById('mySales').innerHTML=personalContracts(visible().filter(c=>(c.client+' '+contractCode(c)).toLowerCase().includes(query.toLowerCase())))"><div id="mySales">${personalContracts(visible())}</div></section><p>Comissions</p>`;}if(page==='Produtos e regras'){root.innerHTML=title('Produtos','Catálogo das empresas autorizadas.')+`<section class="panel">${table(['Produto','Empresa','Mensalidade / venda','Implementação'],products().map(p=>[esc(p.name),esc(companyName(p.company)),money(p.baseMonthly||0),money(p.baseSetup||0)]))}</section><p>Comissions</p>`;}if(page==='Metas'){root.innerHTML=title('Metas por empresa','Metas dos períodos e empresas liberados para consulta.')+`<section class="panel">${table(['Período','Empresa','Novos clientes','Faturamento','MRR'],scopedGoals().map(g=>[esc(periodLabel(g.period)),esc(companyName(g.company)),g.clients??'—',g.revenue==null?'—':money(g.revenue),g.mrr==null?'—':money(g.mrr)]))}</section><p>Comissions</p>`;}if(page==='Recebíveis'){root.innerHTML=title('Meus recebíveis','Cobranças das vendas em que você participa.')+`<section class="panel">${table(['Contrato','Vencimento','Valor','Situação'],state.invoices.filter(i=>!i.archived&&visible().some(c=>c.id===i.contractId)).map(i=>[esc(contractCode(state.contracts.find(c=>c.id===i.contractId))),esc(i.due),money(i.amount),i.paidAt?'Recebido':'Pendente']))}</section><p>Comissions</p>`;}}
function personalContracts(list){return table(['Contrato / cliente','Empresa / produto','Mensalidade / venda','Implementação','Data','Status'],list.map(c=>[`${esc(contractCode(c))}<div>${esc(c.client)}</div>`,`${esc(companyName(c.company))}<div class="small">${esc(product(c.product)?.name||c.plan)}</div>`,money(c.monthly),money(c.setup),esc(c.start),esc(c.status)]));}
const managerSubmitSale=submitSale;
submitSale=async function(f){if(!['Vendedor','Colaborador'].includes(user().role))return managerSubmitSale(f);const form=document.getElementById('saleForm');if(form.dataset.saving)return;form.dataset.saving='1';const buttons=form.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await api('seller-sale',{version:cloudVersion,sale:{requestId:(saleDraft.requestId??=crypto.randomUUID()),company:f.get('company'),client:f.get('client'),date:f.get('date'),due:f.get('due'),cycles:Number(f.get('cycles')),items:saleDraft.items.map(i=>({product:i.product,value:i.value,setup:i.setup,parts:i.parts}))}});const requestId=saleDraft.requestId;await loadCloud();document.getElementById('modal').close();saleDraft=null;page='Contratos';render();const created=state.contracts.find(c=>c.portalRequestId===requestId);toast('Rascunho salvo. Anexe o documento e envie para validação.');if(created)openSalePortal(created.id);}catch(e){toast(e.message);}finally{delete form.dataset.saving;buttons.forEach(b=>b.disabled=false);}};
window.addEventListener('beforeunload',e=>{if(cloudSaving||cloudPending){e.preventDefault();e.returnValue='';}});
(async()=>{if(new URLSearchParams(location.hash.slice(1)).has('invite'))return authScreen(true);if(!cloudSession)return authScreen();try{await loadCloud()}catch{localStorage.removeItem('comissions-auth-session');cloudSession=null;authScreen();}})();
